import brentq = require( './index' );

/**
* Callback function.
*
* @param x - input value
* @returns result
*/
function f( x: number ): number {
	return x * x - 1.0;
}

// TESTS //

// The function returns a solution object...
{
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectType Results
	brentq( ( x: number, y: number ) => x * x - y, 0.0, 2.0, 100, 2e-12, 8.88e-16, [ 1.0 ] ); // $ExpectType Results
}

// The compiler throws an error if the function is provided an invalid first argument...
{
	brentq( true, 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( false, 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( 5, 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( [], 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( {}, 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( 'abc', 0.0, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid second argument...
{
	brentq( f, true, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, false, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, [], 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, {}, 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 'abc', 2.0, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid third argument...
{
	brentq( f, 0.0, true, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, false, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, [], 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, {}, 100, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 'abc', 100, 2e-12, 8.88e-16, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid fourth argument...
{
	brentq( f, 0.0, 2.0, true, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, false, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, [], 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, {}, 2e-12, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 'abc', 2e-12, 8.88e-16, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid fifth argument...
{
	brentq( f, 0.0, 2.0, 100, true, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, false, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, [], 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, {}, 8.88e-16, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 'abc', 8.88e-16, [] ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid sixth argument...
{
	brentq( f, 0.0, 2.0, 100, 2e-12, true, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, false, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, [], [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, {}, [] ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, 'abc', [] ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid seventh argument...
{
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, true ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, false ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, {} ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, 'abc' ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16, 123 ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	brentq( f, 0.0, 2.0 ); // $ExpectError
	brentq( f, 0.0, 2.0, 100 ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12 ); // $ExpectError
	brentq( f, 0.0, 2.0, 100, 2e-12, 8.88e-16 ); // $ExpectError
}
